import{_ as e,o as t,c as n,a2 as s}from"./chunks/framework.D66Xq0Kv.js";const g=JSON.parse('{"title":"23. Säkerhet och åtkomst","description":"","frontmatter":{},"headers":[],"relativePath":"sv/chapters/23-sakerhet-och-atkomst.md","filePath":"sv/chapters/23-sakerhet-och-atkomst.md"}'),r={name:"sv/chapters/23-sakerhet-och-atkomst.md"};function i(l,a,o,d,h,k){return t(),n("div",null,[...a[0]||(a[0]=[s(`<h1 id="_23-sakerhet-och-atkomst" tabindex="-1">23. Säkerhet och åtkomst <a class="header-anchor" href="#_23-sakerhet-och-atkomst" aria-label="Permalink to &quot;23. Säkerhet och åtkomst&quot;">​</a></h1><p>Bokhandelns databas innehåller information som många kan behöva använda, men inte alla behöver kunna göra samma saker med den.</p><p>Kunder ska kunna se vilka böcker som finns. Personal kan behöva ändra lagersaldon. En administratör kan behöva hantera användarkonton och databasens struktur. Men det betyder inte att alla dessa roller ska få läsa och förändra all information.</p><p>En viktig del av databassäkerhet är därför att bestämma <strong>vem som får göra vad, med vilken information och under vilka förutsättningar</strong>.</p><h2 id="grund" tabindex="-1">Grund <a class="header-anchor" href="#grund" aria-label="Permalink to &quot;Grund&quot;">​</a></h2><h3 id="att-identifiera-och-tillata" tabindex="-1">Att identifiera och tillåta <a class="header-anchor" href="#att-identifiera-och-tillata" aria-label="Permalink to &quot;Att identifiera och tillåta&quot;">​</a></h3><p>Vi behöver skilja mellan två frågor:</p><ul><li><strong>Autentisering:</strong> Vem är det som försöker ansluta?</li><li><strong>Auktorisation:</strong> Vad får den identifierade aktören göra?</li></ul><p>Autentisering kan exempelvis ske med användarnamn och lösenord, certifikat eller en identitetstjänst. Auktorisation handlar om vilka rättigheter den identiteten har.</p><p>Vi kan också skilja mellan <strong>databasanvändaren</strong> som en applikation ansluter med och <strong>slutanvändaren</strong> som är inloggad i applikationen.</p><p>Om hundra kunder använder bokhandelns webbplats behöver det inte innebära hundra olika databaskonton. Webbapplikationen kan använda en särskild databasidentitet och själv kontrollera vilka kunduppgifter den enskilde kunden får se.</p><h3 id="anvandare-och-rattigheter" tabindex="-1">Användare och rättigheter <a class="header-anchor" href="#anvandare-och-rattigheter" aria-label="Permalink to &quot;Användare och rättigheter&quot;">​</a></h3><p>I MySQL kan vi skapa ett konto för bokhandelns applikation:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CREATE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> USER</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> &#39;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bookstore_app</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&#39;@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;localhost&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">IDENTIFIED </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">BY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;ett-starkt-unikt-losenord&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>Det här är ett syntaxexempel. Ett riktigt lösenord ska hanteras säkert och inte sparas i versionshanterade skript.</p><p>I MySQL ingår även anslutningsvärden som <code>localhost</code> i hur ett konto identifieras. Andra databassystem organiserar användare och anslutningsbehörigheter annorlunda.[^users]</p><p>[^users]: <code>CREATE USER</code> och hantering av identiteter varierar mellan databassystem. Exemplet använder MySQL:s kontomodell. I andra miljöer kan roller, externa identitetsleverantörer eller serverövergripande inloggningar användas.</p><p>Att ett konto finns betyder inte att det automatiskt har rätt att läsa och förändra bokhandelns tabeller.</p><h3 id="grant-–-att-tilldela-rattigheter" tabindex="-1">GRANT – att tilldela rättigheter <a class="header-anchor" href="#grant-–-att-tilldela-rattigheter" aria-label="Permalink to &quot;GRANT – att tilldela rättigheter&quot;">​</a></h3><p>Vi kan ge kontot rätt att läsa information om produkterna:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GRANT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> SELECT</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ON</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> bookstore</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">products</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">TO</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;bookstore_app&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;localhost&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p><code>GRANT</code> tilldelar en viss rättighet till en identitet.</p><p>Nu kan kontot läsa <code>products</code>, men den här instruktionen ger inte rätt att ändra pris, ta bort produkter eller skapa nya tabeller.</p><p>Om ett administrativt system också behöver ändra lagersaldon kan vi ge en annan identitet en mer avgränsad rättighet:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GRANT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> SELECT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">UPDATE</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ON</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> bookstore</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">products</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">TO</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;bookstore_staff&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;localhost&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>Det förutsätter att kontot <code>bookstore_staff</code> redan finns. Även detta exempel är förenklat: <code>UPDATE</code> på hela tabellen ger möjlighet att ändra <em>alla</em> kolumner, inte bara lagersaldot.</p><h3 id="minsta-privilegium" tabindex="-1">Minsta privilegium <a class="header-anchor" href="#minsta-privilegium" aria-label="Permalink to &quot;Minsta privilegium&quot;">​</a></h3><p>Principen om <strong>minsta privilegium</strong> (<em>least privilege</em>) innebär att en identitet bara får de rättigheter den faktiskt behöver.</p><p>Det är ofta ett bättre utgångsläge att börja med få rättigheter och lägga till dem efter behov än att ge alla full åtkomst.</p><p>Om webbapplikationen bara behöver läsa produktkatalogen bör den till exempel inte kunna:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">DROP</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> TABLE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> products;</span></span></code></pre></div><p>Även om applikationen aldrig avser att utföra en sådan operation är det värdefullt att databasen kan neka den.</p><p>Vi skyddar alltså inte bara mot avsiktliga angrepp, utan också mot programmeringsfel och oavsiktliga handlingar.</p><h3 id="revoke-–-att-ta-tillbaka-rattigheter" tabindex="-1">REVOKE – att ta tillbaka rättigheter <a class="header-anchor" href="#revoke-–-att-ta-tillbaka-rattigheter" aria-label="Permalink to &quot;REVOKE – att ta tillbaka rättigheter&quot;">​</a></h3><p>Vi kan återkalla en tidigare tilldelad rättighet:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">REVOKE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> UPDATE</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ON</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> bookstore</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">products</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;bookstore_staff&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;localhost&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>Efter detta har identiteten inte längre denna direkta <code>UPDATE</code>-rättighet på tabellen.</p><p>Men det är viktigt att komma ihåg att rättigheter också kan komma från andra tilldelningar, exempelvis roller eller rättigheter på en överordnad nivå. <code>REVOKE</code> av en enda tilldelning betyder därför inte alltid att alla möjligheter till samma operation försvinner.</p><h3 id="roller" tabindex="-1">Roller <a class="header-anchor" href="#roller" aria-label="Permalink to &quot;Roller&quot;">​</a></h3><p>I stället för att hantera varje kontos rättigheter separat kan vi i många databassystem använda <strong>roller</strong>.</p><p>I MySQL 8 kan vi exempelvis skapa en roll för dem som behöver läsa bokhandelns produkter:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CREATE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ROLE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;catalog_reader&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GRANT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> SELECT</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ON</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> bookstore</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">products</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">TO</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;catalog_reader&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GRANT</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;catalog_reader&#39;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">TO</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;bookstore_app&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">@</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;localhost&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>Detta förutsätter att applikationskontot redan finns. För att rollens rättigheter ska vara aktiva måste även rollaktiveringen hanteras enligt databasens regler, till exempel genom en standardroll eller genom att aktivera rollen i sessionen.[^roles]</p><p>[^roles]: MySQL 8 stöder roller, men tilldelade roller är inte alltid automatiskt aktiva. PostgreSQL och SQL Server har andra rollmodeller och syntaxer för tilldelning och aktivering. Kontrollera alltid de faktiska effektiva rättigheterna.</p><p>En roll är alltså ett sätt att samla <strong>vilka handlingar en viss funktion behöver kunna utföra</strong>.</p><h2 id="avancerat" tabindex="-1">Avancerat <a class="header-anchor" href="#avancerat" aria-label="Permalink to &quot;Avancerat&quot;">​</a></h2><h3 id="behorighet-pa-flera-nivaer" tabindex="-1">Behörighet på flera nivåer <a class="header-anchor" href="#behorighet-pa-flera-nivaer" aria-label="Permalink to &quot;Behörighet på flera nivåer&quot;">​</a></h3><p>Vi kan tänka oss flera nivåer av åtkomst:</p><table tabindex="0"><thead><tr><th>Nivå</th><th>Exempel</th></tr></thead><tbody><tr><td>Databasserver</td><td>Får identiteten ansluta till databashanteraren?</td></tr><tr><td>Databas eller schema</td><td>Får identiteten använda en viss del av databasen?</td></tr><tr><td>Tabell eller View</td><td>Får identiteten läsa eller ändra ett visst databasobjekt?</td></tr><tr><td>Kolumn</td><td>Får identiteten läsa eller ändra vissa attribut?</td></tr><tr><td>Rad eller informationspost</td><td>Vilka enskilda poster får en användare se?</td></tr></tbody></table><p>Alla SQL-system hanterar inte dessa nivåer på samma sätt. Särskilt <strong>radbaserad åtkomstkontroll</strong> varierar mellan databassystem.</p><p>I en webbapplikation måste vi dessutom avgöra vilka rättigheter den inloggade kunden har, även om många kunder delar samma databasanslutning.</p><h3 id="en-view-som-begransat-informationsgranssnitt" tabindex="-1">En View som begränsat informationsgränssnitt <a class="header-anchor" href="#en-view-som-begransat-informationsgranssnitt" aria-label="Permalink to &quot;En View som begränsat informationsgränssnitt&quot;">​</a></h3><p>I kapitel 17 såg vi hur en View kan visa en del av informationen från en tabell.</p><p>Anta att kundtabellen innehåller både namn, e-postadress och födelsedatum, men att en intern namnlista bara behöver identifierare och namn:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">CREATE</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> VIEW</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> customer_names</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> AS</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> id, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">name</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> customers;</span></span></code></pre></div><p>Vi kan ge en särskild roll rätt att läsa just denna View:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">GRANT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> SELECT</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ON</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> bookstore</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">customer_names</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">TO</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;name_reader&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>Det förutsätter att rollen redan är skapad.</p><p>Om rollen inte också har åtkomst till den underliggande tabellen kan vyn utgöra ett avgränsat gränssnitt. Men säkerheten beror på <strong>hur databassystemet kontrollerar behörigheter när vyn körs</strong> och vilka andra rättigheter som finns.[^views]</p><p>[^views]: I MySQL kan vyer exempelvis använda <code>SQL SECURITY DEFINER</code> eller <code>INVOKER</code>. Det påverkar vilken identitets behörigheter som används för åtkomst till underliggande objekt. Vyer är inte automatiskt en fullständig säkerhetsgräns och kan behöva kompletteras med andra mekanismer.</p><p>Vi ska alltså inte anta att en View skyddar information bara för att den visar färre kolumner.</p><h3 id="radbaserad-atkomst" tabindex="-1">Radbaserad åtkomst <a class="header-anchor" href="#radbaserad-atkomst" aria-label="Permalink to &quot;Radbaserad åtkomst&quot;">​</a></h3><p>Anta att varje kund ska få se sina egna beställningar, men inte andras.</p><p>En applikation kan formulera:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> id, ordered_at</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> orders</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> customer_id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> @customerId;</span></span></code></pre></div><p>Parametern <code>@customerId</code> är här ett exempel på en parametriserad Query från applikationskod, inte en fristående SQL-variabel som fungerar likadant i alla databassystem.</p><p>Det avgörande är <strong>varifrån kund-id kommer</strong>.</p><p>Om applikationen låter användaren ange vilket kund-id som helst utan kontroll kan kunden kanske läsa någon annans beställningar.</p><p>Applikationen behöver därför härleda identiteten från en betrodd inloggningsprocess och kontrollera rätten till den efterfrågade informationen.</p><p>Vissa databassystem har dessutom mekanismer för radbaserade säkerhetsregler, exempelvis PostgreSQL:s <em>Row-Level Security</em> och SQL Servers <em>Row-Level Security</em>. MySQL saknar en direkt motsvarande generell inbyggd funktion, vilket gör applikationskontroller och väl utformade databasgränssnitt särskilt viktiga i sådana miljöer.[^rls]</p><p>[^rls]: Funktioner, begränsningar och säkerhetsmodell för radbaserade behörigheter är databasspecifika. Rätt utformning kräver bland annat förståelse för hur identitet och sessionskontext förs vidare från applikationen.</p><h3 id="sql-injektion-ar-inte-bara-en-fraga-om-indata" tabindex="-1">SQL-injektion är inte bara en fråga om indata <a class="header-anchor" href="#sql-injektion-ar-inte-bara-en-fraga-om-indata" aria-label="Permalink to &quot;SQL-injektion är inte bara en fråga om indata&quot;">​</a></h3><p>Vi mötte SQL-injektion i kapitel 22.</p><p>Parametriserade Queries gör att en användares text inte kan tolkas som SQL-instruktioner där en parameter används som värde.</p><p>Men även en applikation med parametriserade Queries behöver begränsa <strong>vad databasidentiteten har rätt att göra</strong>.</p><p>Om ett angrepp ändå ger tillgång till en applikations databasanslutning bör kontot inte ha fler privilegier än nödvändigt.</p><p>Det är ett exempel på <strong>försvar på flera nivåer</strong> (<em>defence in depth</em>): flera oberoende skydd som minskar konsekvenserna om ett av dem misslyckas.</p><h3 id="saker-information-ar-mer-an-rattigheter" tabindex="-1">Säker information är mer än rättigheter <a class="header-anchor" href="#saker-information-ar-mer-an-rattigheter" aria-label="Permalink to &quot;Säker information är mer än rättigheter&quot;">​</a></h3><p>Även om åtkomstkontrollen fungerar behöver vi tänka på hur informationen hanteras.</p><p>Exempelvis:</p><ul><li><strong>Överföring:</strong> Är anslutningen till databasen krypterad, och kontrollerar klienten serverns identitet?</li><li><strong>Lagring:</strong> Skyddas databaser, säkerhetskopior och lagringsmedier på ett lämpligt sätt?</li><li><strong>Hemligheter:</strong> Hur förvaras lösenord, anslutningssträngar och andra åtkomstuppgifter?</li><li><strong>Loggning:</strong> Vilka händelser behöver kunna spåras, och hur undviker vi att loggarna avslöjar känslig information?</li><li><strong>Säkerhetskopiering:</strong> Går informationen att återställa efter fel, angrepp eller oavsiktlig radering?</li></ul><p>Kryptering, åtkomstkontroll och säkerhetskopiering löser olika problem. Ingen enskild mekanism ersätter de andra.</p><h3 id="kryptering-och-hashning-–-tva-olika-syften" tabindex="-1">Kryptering och hashning – två olika syften <a class="header-anchor" href="#kryptering-och-hashning-–-tva-olika-syften" aria-label="Permalink to &quot;Kryptering och hashning – två olika syften&quot;">​</a></h3><p>När vi lagrar känslig information behöver vi först avgöra <strong>om originalvärdet någonsin ska kunna läsas igen</strong>.</p><p><strong>Kryptering</strong> omvandlar ett värde till en form som kan återställas med rätt nyckel. Det kan behövas för uppgifter som en behörig verksamhetsprocess senare måste kunna läsa.</p><p><strong>Hashning</strong> beräknar däremot ett värde som inte är avsett att kunna omvandlas tillbaka till originalet. För lösenord använder vi särskilda, avsiktligt resurskrävande <strong>lösenordshashningsalgoritmer</strong> – inte en vanlig snabb hashfunktion.</p><p>I MySQL finns exempelvis funktionen <code>SHA2()</code>:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> SHA2(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;ett exempelvärde&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">256</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>Det är ett exempel på <strong>vanlig hashning</strong>, bland annat användbar i sammanhang där vi behöver ett kontrollvärde. <strong>Det är inte ett lämpligt sätt att lagra lösenord.</strong> En snabb hashfunktion som SHA-256 gör det möjligt att pröva stora mängder lösenordsgissningar på kort tid.</p><p>För lösenord använder vi hellre etablerade bibliotek med exempelvis <strong>Argon2id</strong> eller andra moderna, anpassade lösenordshashningsalgoritmer.[^password-storage]</p><p>[^password-storage]: Se <a href="https://cheatsheetseries.owasp.org/cheatsheets/Password_Storage_Cheat_Sheet.html" target="_blank" rel="noreferrer">OWASP Password Storage Cheat Sheet</a>. Där beskrivs rekommenderade algoritmer, salt, parametrar och migrering av äldre lösenordshashar. Vanlig SHA-256, även med ett enkelt salt, är inte en ersättning för lösenordshashning.</p><h3 id="att-skapa-och-verifiera-ett-losenordshashvarde" tabindex="-1">Att skapa och verifiera ett lösenordshashvärde <a class="header-anchor" href="#att-skapa-och-verifiera-ett-losenordshashvarde" aria-label="Permalink to &quot;Att skapa och verifiera ett lösenordshashvärde&quot;">​</a></h3><p>Anta att bokhandelns applikation har konton för personalen.</p><p>När en användare skapar ett lösenord behöver programmet:</p><ol><li>Ta emot lösenordet via en skyddad anslutning.</li><li>Låta ett lösenordshashningsbibliotek skapa ett hashvärde med ett <strong>unikt salt</strong> och lämpliga kostnadsparametrar.</li><li>Lagra den resulterande lösenordsrepresentationen i databasen – <strong>inte lösenordet i klartext</strong>.</li></ol><p>Vi kan illustrera skillnaden med pseudokod; funktionsnamnen nedan är <strong>inte inbyggda SQL-funktioner</strong>:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>stored_hash = PasswordHasher.Hash(password)</span></span>
<span class="line"><span>is_valid = PasswordHasher.Verify(password_attempt, stored_hash)</span></span></code></pre></div><p>Vid inloggning verifierar programmet det angivna lösenordet mot det lagrade värdet. Det behöver inte, och ska inte försöka, dekryptera lösenordet.</p><p>Salt är inte detsamma som en hemlig krypteringsnyckel. Ett slumpmässigt, unikt salt hjälper oss bland annat att undvika identiska hashvärden för identiska lösenord och försvårar förberäknade attacker. Etablerade bibliotek brukar själva generera och lagra salt tillsammans med algoritm och kostnadsparametrar i en strukturerad hashrepresentation.</p><p>Det är också en skillnad mellan <strong>lösenordshashning</strong> och att använda en hash för exempelvis filintegritet eller jämförelse av innehåll. Vi ska välja metod efter vilket problem vi vill lösa.</p><h3 id="att-kryptera-lagrad-information" tabindex="-1">Att kryptera lagrad information <a class="header-anchor" href="#att-kryptera-lagrad-information" aria-label="Permalink to &quot;Att kryptera lagrad information&quot;">​</a></h3><p>MySQL har också funktioner för symmetrisk kryptering, exempelvis <code>AES_ENCRYPT()</code> och <code>AES_DECRYPT()</code>. Det visar att kryptering i vissa miljöer kan utföras av databashanteraren.</p><p>Men valet av funktion räcker inte för att skapa ett säkert system. Vi behöver bland annat hantera <strong>nycklar, krypteringsläge, initialiseringsvärden, integritetsskydd och åtkomst</strong> på ett genomtänkt sätt. Vi bör inte bygga en egen kryptografisk lösning kring enstaka SQL-funktioner.</p><p>I många applikationer är det lämpligt att utföra krypteringen med ett välunderhållet bibliotek <strong>innan värdet skickas till databasen</strong>. Då kan databasen lagra exempelvis krypterad binärdata tillsammans med den metadata som behövs för att senare kunna dekryptera den:</p><table tabindex="0"><thead><tr><th>customer_id</th><th>encrypted_note</th><th>key_version</th></tr></thead><tbody><tr><td>1</td><td><em>(krypterad binärdata)</em></td><td>2</td></tr></tbody></table><p>Exemplet beskriver principen, inte en fullständig säker datamodell. Beroende på algoritm behöver vi också hantera exempelvis <em>nonce/IV</em> och autentiseringstagg. Nyckeln ska i möjligaste mån förvaras <strong>separat från den krypterade informationen</strong>, exempelvis i en avsedd nyckelhanteringstjänst.[^crypto-storage]</p><p>[^crypto-storage]: Se <a href="https://cheatsheetseries.owasp.org/cheatsheets/Cryptographic_Storage_Cheat_Sheet.html" target="_blank" rel="noreferrer">OWASP Cryptographic Storage Cheat Sheet</a> för vägledning om kryptering i applikations-, databas- och lagringslager samt säker hantering av nycklar och krypteringslägen.</p><p>Kryptering av enskilda fält är inte heller samma sak som kryptering av hela databasens lagringsfiler eller säkerhetskopior. De skyddar mot delvis olika hot.</p><h3 id="nar-algoritmen-eller-nyckeln-behover-bytas" tabindex="-1">När algoritmen eller nyckeln behöver bytas <a class="header-anchor" href="#nar-algoritmen-eller-nyckeln-behover-bytas" aria-label="Permalink to &quot;När algoritmen eller nyckeln behöver bytas&quot;">​</a></h3><p>Kryptografiska skydd behöver kunna förändras. En algoritm kan få kända svagheter, en nyckel kan misstänkas vara röjd eller säkerhetskraven kan förändras.</p><p>För <strong>reversibelt krypterade data</strong> kan vi, om vi fortfarande har tillgång till nyckeln och originalinformationen behöver bevaras:</p><ol><li>Identifiera vilken algoritm och nyckelversion som användes.</li><li>Dekryptera uppgiften med den gamla nyckeln i en kontrollerad miljö.</li><li>Kryptera om den med den nya algoritmen eller nyckeln.</li><li>Kontrollera resultatet och avveckla det gamla skyddet när det är säkert att göra det.</li></ol><p>Under en övergång kan systemet behöva kunna läsa både gamla och nya format. Därför är <strong>versionsinformation</strong> en viktig del av datamodellen.</p><p>I vissa system används <em>envelope encryption</em>: själva data krypteras med en datanyckel, som i sin tur skyddas med en separat nyckel. Då kan man ibland <strong>kryptera om datanyckeln</strong> med en ny överordnad nyckel utan att kryptera om alla datavärden. Om själva datanyckeln eller krypteringsalgoritmen måste bytas kan även innehållet behöva krypteras om.[^key-management]</p><p>[^key-management]: Se <a href="https://cheatsheetseries.owasp.org/cheatsheets/Key_Management_Cheat_Sheet.html" target="_blank" rel="noreferrer">OWASP Key Management Cheat Sheet</a>. Att byta nyckel kräver även hänsyn till äldre säkerhetskopior, återställningsförmåga och hur gamla nycklar slutligen ska avvecklas.</p><h3 id="nar-losenordens-skydd-behover-ersattas" tabindex="-1">När lösenordens skydd behöver ersättas <a class="header-anchor" href="#nar-losenordens-skydd-behover-ersattas" aria-label="Permalink to &quot;När lösenordens skydd behöver ersättas&quot;">​</a></h3><p>För lösenordshashar fungerar inte metoden ovan: vi kan inte dekryptera en hash och sedan skapa ett nytt hashvärde av det ursprungliga lösenordet.</p><p>En vanlig migreringsmetod är därför att <strong>uppgradera hashvärdet vid en lyckad inloggning</strong>:</p><ol><li>Läs den lagrade lösenordsrepresentationen och identifiera dess algoritm och parametrar.</li><li>Verifiera användarens inmatade lösenord enligt den gamla metoden.</li><li>Skapa en ny lösenordshash med den moderna metoden.</li><li>Ersätt den gamla representationen.</li></ol><p>Men vad gör vi med användare som inte loggar in?</p><p>Om det gamla skyddet är för svagt, eller misstänks ha komprometterats, kan vi behöva <strong>ogiltigförklara de gamla autentiseringsuppgifterna</strong> och kräva att berörda användare skapar nya lösenord genom en säker återställningsprocess.</p><p>Vi ska också skilja mellan att skapa <strong>en ny hash av samma lösenord</strong> och att faktiskt <strong>byta lösenord</strong>. Om äldre hashvärden redan har stulits kan ett algoritmbyte inte göra de stulna värdena ogjorda; angriparen kan fortfarande försöka knäcka dem. Vid kompromettering kan nya lösenord, återkallade sessioner och andra incidentåtgärder behövas.</p><p>Den här typen av förändringar bör planeras redan när autentiseringslösningen byggs. Systemet behöver exempelvis kunna hantera mer än ett lösenordsformat under en övergång utan att behålla osäkra format längre än nödvändigt.</p><h3 id="informationsvardet-och-skyddets-livslangd" tabindex="-1">Informationsvärdet och skyddets livslängd <a class="header-anchor" href="#informationsvardet-och-skyddets-livslangd" aria-label="Permalink to &quot;Informationsvärdet och skyddets livslängd&quot;">​</a></h3><p>Det finns en viktig skillnad mellan <strong>informationen vi behöver bevara</strong> och <strong>metoden vi använder för att skydda den</strong>.</p><p>En krypterad kunduppgift kan fortfarande ha ett giltigt användningsområde även om krypteringsalgoritmen blivit föråldrad. Då vill vi kanske bevara informationen men byta skydd.</p><p>För ett lösenord är syftet inte att bevara den ursprungliga texten. Vi behöver i stället bevara eller återupprätta användarens <strong>möjlighet att legitimera sig på ett säkert sätt</strong>.</p><p>Det innebär att ett väl utformat system ibland måste kunna <strong>migrera information</strong>, och ibland måste kunna <strong>kassera gamla autentiseringsuppgifter</strong>.</p><p>Båda är exempel på att säkerhet också handlar om hur informationssystem kan förändras över tid.</p><h3 id="personuppgifter-och-dataminimering" tabindex="-1">Personuppgifter och dataminimering <a class="header-anchor" href="#personuppgifter-och-dataminimering" aria-label="Permalink to &quot;Personuppgifter och dataminimering&quot;">​</a></h3><p>I bokhandelns kundregister finns namn, e-postadress och kanske födelsedatum.</p><p>Men behöver vi verkligen kundens födelsedatum för att sälja en bok?</p><p>Frågan handlar inte enbart om vilka data vi <em>kan</em> lagra, utan också om <strong>varför vi lagrar dem och hur länge de behövs</strong>.</p><p>Dataminimering innebär att vi inte samlar in mer personuppgifter än vad som är nödvändigt för ett berättigat ändamål.</p><p>Den principen påverkar datamodelleringen redan innan vi börjar diskutera <code>GRANT</code> och <code>REVOKE</code>.</p><p>Den kan också skapa en viktig spänning: vissa uppgifter behöver bevaras för exempelvis bokföring och historik, medan andra bör kunna rättas eller raderas enligt tillämpliga regler. Sådana beslut kräver både verksamhetskunskap och juridisk bedömning.</p><h3 id="loggning-och-sparbarhet" tabindex="-1">Loggning och spårbarhet <a class="header-anchor" href="#loggning-och-sparbarhet" aria-label="Permalink to &quot;Loggning och spårbarhet&quot;">​</a></h3><p>Det kan vara viktigt att i efterhand förstå vem som ändrade ett pris eller tog bort en post.</p><p>Men en vanlig <code>UPDATE</code> säger inte automatiskt <em>vem</em> som begärde ändringen eller <em>varför</em>.</p><p>För spårbarhet kan vi behöva logga administrativa handlingar, använda särskilda historiktabeller eller stöd för databasgranskning (<em>auditing</em>).</p><p>Även här behöver vi skilja mellan databasens tekniska identitet och applikationens slutanvändare. Om alla ändringar kommer från <code>bookstore_app</code> räcker det inte att bara logga databasens kontonamn för att veta vilken anställd som gjorde ändringen.</p><p>En logg ska dessutom skyddas från obehörig ändring och inte innehålla fler personuppgifter än nödvändigt.</p><h3 id="tillganglighet-ar-ocksa-sakerhet" tabindex="-1">Tillgänglighet är också säkerhet <a class="header-anchor" href="#tillganglighet-ar-ocksa-sakerhet" aria-label="Permalink to &quot;Tillgänglighet är också säkerhet&quot;">​</a></h3><p>Informationssäkerhet brukar ofta beskrivas genom tre grundläggande mål:</p><table tabindex="0"><thead><tr><th>Mål</th><th>Vad det betyder</th></tr></thead><tbody><tr><td><strong>Konfidentialitet</strong></td><td>Information ska inte avslöjas för obehöriga.</td></tr><tr><td><strong>Integritet</strong></td><td>Information ska vara korrekt och skyddad mot otillåten eller oavsiktlig förändring.</td></tr><tr><td><strong>Tillgänglighet</strong></td><td>Behöriga användare ska kunna komma åt information när de behöver den.</td></tr></tbody></table><p>En databas som är perfekt skyddad mot läsning men inte kan användas av verksamheten är inte en fungerande lösning.</p><p>Säkerhetsarbetet innebär därför avvägningar mellan skydd, funktion, administration och återställningsförmåga.</p><h3 id="sakerhetsregler-som-en-del-av-datamodellen" tabindex="-1">Säkerhetsregler som en del av datamodellen <a class="header-anchor" href="#sakerhetsregler-som-en-del-av-datamodellen" aria-label="Permalink to &quot;Säkerhetsregler som en del av datamodellen&quot;">​</a></h3><p>Vi har tidigare diskuterat datamodellen som ett avtal om vad informationen betyder.</p><p>Nu kan vi lägga till en dimension: modellen och dess omgivande behörighetsregler uttrycker också <strong>vem som får veta något och vem som får förändra det</strong>.</p><p>En tabell kan innehålla korrekt information och en Query kan vara tekniskt giltig, men det betyder inte att alla ska kunna köra den.</p><p>Därför behöver vi skilja mellan tre frågor:</p><p><strong>Är informationen korrekt representerad?</strong></p><p><strong>Kan databasen besvara vår Query?</strong></p><p><strong>Har den som frågar rätt att få svaret?</strong></p><p>Alla tre kan vara nödvändiga för att ett informationssystem ska fungera ansvarsfullt.</p><h2 id="reflektion" tabindex="-1">Reflektion <a class="header-anchor" href="#reflektion" aria-label="Permalink to &quot;Reflektion&quot;">​</a></h2><ol><li>Varför räcker det inte att kontrollera användarens behörighet i webbgränssnittet om databaskontot samtidigt har full åtkomst?</li><li>Vad är skillnaden mellan att begränsa information med en View och att faktiskt kontrollera vem som får läsa den?</li><li>Hur påverkas vår datamodell av frågan om vilka uppgifter vi bör lagra – inte bara vilka uppgifter vi tekniskt kan lagra?</li></ol>`,158)])])}const m=e(r,[["render",i]]);export{g as __pageData,m as default};
